const data = await ctx.call("records", {});
console.log(data);
const best = new Map();
for (const r of data.records) {
  const old = best.get(r.sku);
  if (!old || r.revision > old.revision) best.set(r.sku, r);
}
const ids = [...best.values()].filter(r => r.active).map(r => r.id).sort();
ctx.done({ids});
